const detection = $input.first().json;

const ACCEPTED_LANGUAGES = ['en', 'cs']; 
const CONFIDENCE_THRESHOLD = 0.75;     

let status = 'rejected_language';
let detectedLanguage = detection.language || 'unknown';
let confidenceScore = detection.score || 0;

const isCorrectLanguage = ACCEPTED_LANGUAGES.includes(detectedLanguage);
const isConfidentEnough = confidenceScore >= CONFIDENCE_THRESHOLD;

if (isCorrectLanguage && isConfidentEnough) {
    status = 'passed_language';
}

return {
    status,
    details: {
        lang: detectedLanguage,
        conf: confidenceScore,
    }
};

const fullDescription = $input.first().json.job_description || "";
const snippet = fullDescription.substring(0, 800); 

return {
  snippet: snippet
};

const items = $('Standardize input').all();

const hardReject = [
'director', 'assistant', 'recruiter', 'intern',  'stáž', 'graduate', 'account manager', 'account executive', 'head', 'sales representative', 'ředitel', 'vedoucí', 'legal', 'prodej','seo', 'lead', 'principal', 'staff', 'part-time', 'part time', 'junior', 'fde', 'student', 'sales executive', 'chief', 'research', 'founding', 'founder', 'deployed', 'senior', 'sr.',

'inference', 'java', 'php', 'c++', 'c#', '.net', 'kotlin', 'rust', 'golang', 'ios', 'android', 'swift', 'react native', 'qa automation', 'test automation', 'kubernetes', 'manual tester', 'ruby', 'fullstack', 'full-stack', 'full stack'
];

return items.map(item => {
  const title = (item.json.job_title || "").toLowerCase();

  let newStatus = 'filtered';

  const isHardReject = hardReject.some(word => title.includes(word));

  if (isHardReject) {
    newStatus = 'rejected_title';
  }
  else {
    newStatus = 'passed_title';
  }

  return {
    json: {
      ...item.json,
      status: newStatus,
    }
  };
});

